class LedgerEntry extends DataClass implements Insertable<LedgerEntry> {
  final int id;
  final int customerId;
  final LedgerType type;
  final int amountPaise;

  /// Customer's balance right after this entry.
  final int balanceAfterPaise;
  final String? note;

  /// Filled by Billing later, when a credit comes from a bill.
  final int? billId;
  final DateTime createdAt;
  const LedgerEntry({
    required this.id,
    required this.customerId,
    required this.type,
    required this.amountPaise,
    required this.balanceAfterPaise,
    this.note,
    this.billId,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['customer_id'] = Variable<int>(customerId);
    {
      map['type'] = Variable<String>(
        $LedgerEntriesTable.$convertertype.toSql(type),
      );
    }
    map['amount_paise'] = Variable<int>(amountPaise);
    map['balance_after_paise'] = Variable<int>(balanceAfterPaise);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    if (!nullToAbsent || billId != null) {
      map['bill_id'] = Variable<int>(billId);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  LedgerEntriesCompanion toCompanion(bool nullToAbsent) {
    return LedgerEntriesCompanion(
      id: Value(id),
      customerId: Value(customerId),
      type: Value(type),
      amountPaise: Value(amountPaise),
      balanceAfterPaise: Value(balanceAfterPaise),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
      billId: billId == null && nullToAbsent
          ? const Value.absent()
          : Value(billId),
      createdAt: Value(createdAt),
    );
  }

  factory LedgerEntry.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return LedgerEntry(
      id: serializer.fromJson<int>(json['id']),
      customerId: serializer.fromJson<int>(json['customerId']),
      type: $LedgerEntriesTable.$convertertype.fromJson(
        serializer.fromJson<String>(json['type']),
      ),
      amountPaise: serializer.fromJson<int>(json['amountPaise']),
      balanceAfterPaise: serializer.fromJson<int>(json['balanceAfterPaise']),
      note: serializer.fromJson<String?>(json['note']),
      billId: serializer.fromJson<int?>(json['billId']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'customerId': serializer.toJson<int>(customerId),
      'type': serializer.toJson<String>(
        $LedgerEntriesTable.$convertertype.toJson(type),
      ),
      'amountPaise': serializer.toJson<int>(amountPaise),
      'balanceAfterPaise': serializer.toJson<int>(balanceAfterPaise),
      'note': serializer.toJson<String?>(note),
      'billId': serializer.toJson<int?>(billId),
      'createdAt': serializer.toJson<DateTime>(createdAt),
    };
  }

  LedgerEntry copyWith({
    int? id,
    int? customerId,
    LedgerType? type,
    int? amountPaise,
    int? balanceAfterPaise,
    Value<String?> note = const Value.absent(),
    Value<int?> billId = const Value.absent(),
    DateTime? createdAt,
  }) => LedgerEntry(
    id: id ?? this.id,
    customerId: customerId ?? this.customerId,
    type: type ?? this.type,
    amountPaise: amountPaise ?? this.amountPaise,
    balanceAfterPaise: balanceAfterPaise ?? this.balanceAfterPaise,
    note: note.present ? note.value : this.note,
    billId: billId.present ? billId.value : this.billId,
    createdAt: createdAt ?? this.createdAt,
  );
  LedgerEntry copyWithCompanion(LedgerEntriesCompanion data) {
    return LedgerEntry(
      id: data.id.present ? data.id.value : this.id,
      customerId: data.customerId.present
          ? data.customerId.value
          : this.customerId,
      type: data.type.present ? data.type.value : this.type,
      amountPaise: data.amountPaise.present
          ? data.amountPaise.value
          : this.amountPaise,
      balanceAfterPaise: data.balanceAfterPaise.present
          ? data.balanceAfterPaise.value
          : this.balanceAfterPaise,
      note: data.note.present ? data.note.value : this.note,
      billId: data.billId.present ? data.billId.value : this.billId,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('LedgerEntry(')
          ..write('id: $id, ')
          ..write('customerId: $customerId, ')
          ..write('type: $type, ')
          ..write('amountPaise: $amountPaise, ')
          ..write('balanceAfterPaise: $balanceAfterPaise, ')
          ..write('note: $note, ')
